import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import { createLabel } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {string} textContent
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader: {load:(url:string)=>THREE.Texture}}} textureLoader
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{primitives:Record<string,Function>}} primitives
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // ---------- Base group ----------
  const root = new THREE.Object3D();
  root.position.set(
    config.position?.x ?? 0,
    config.position?.y ?? 0,
    config.position?.z ?? 0
  );
  root.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  root.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // ---------- Background textured plane ----------
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;
  texture.needsUpdate = true;

  const atlasRect = { width: 512, height: 320 };
  const aspect = atlasRect.width / atlasRect.height;
  const bgGeometry = new THREE.PlaneGeometry(aspect, 1);
  const bgMaterial = new MeshBasicNodeMaterial({
    mapNode: texture(texture),
    transparent: true,
    side: THREE.DoubleSide,
    depthTest: false,
    depthWrite: false,
  });
  const bgMesh = new THREE.Mesh(bgGeometry, bgMaterial);
  bgMesh.renderOrder = 0;
  root.add(bgMesh);

  // ---------- Text label ----------
  // Using the shared font atlas utility to create a mesh that samples the MSDF atlas.
  // The utility abstracts away glyph geometry creation.
  const textMesh = createLabel(ctx.fontAtlas, {
    text: config.textContent,
    font: 'display', // Lora – mapped in the atlas as “display”
    size: 0.34, // headline scale from design tokens
    color: '#16161d', // ink
    align: 'center',
    // UV region of the atlas (the same region used for the background texture)
    uvRegion: {
      x: 0,
      y: 0,
      width: atlasRect.width,
      height: atlasRect.height,
      atlasWidth: texture.image?.width ?? atlasRect.width,
      atlasHeight: texture.image?.height ?? atlasRect.height,
    },
  });
  textMesh.position.set(0, 0, 0.01); // slightly in front of background
  root.add(textMesh);

  // ---------- Apply cinematic primitives ----------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  // ---------- Handlers placeholder ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry and material of background
    bgGeometry.dispose();
    bgMaterial.dispose();
    // Dispose texture if it was created exclusively for this node (fallback safe)
    if (texture && texture.dispose) texture.dispose();

    // Dispose text mesh resources (assumes it implements dispose)
    if (textMesh && typeof textMesh.dispose === 'function') {
      textMesh.dispose();
    }

    // Kill any GSAP timelines that might have been attached
    gsap.globalTimeline.clear();
  };

  return root;
}
